import{_ as l,c as p,o as a,af as e}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"周易尚氏学说例","description":"周易尚氏学 - 周易尚氏学说例","frontmatter":{"title":"周易尚氏学说例","description":"周易尚氏学 - 周易尚氏学说例"},"headers":[],"relativePath":"zh/classics/shangshi/004.md","filePath":"zh/classics/shangshi/004.md"}'),s={name:"zh/classics/shangshi/004.md"};function t(r,i,n,c,_,o){return a(),p("div",null,[...i[0]||(i[0]=[e('<h1 id="周易尚氏学说例" tabindex="-1">周易尚氏学说例 <a class="header-anchor" href="#周易尚氏学说例" aria-label="Permalink to “周易尚氏学说例”">​</a></h1><ul><li><p>乾坤二卦为六十四卦之根本。其六爻爻辞。祇以明上下。别贵贱。及卦运之兴衰。初终之时位。树六十四卦之准则。至于有无应与当位不当位之恒例。皆未之及。而六爻之后。复赘以用九用六数语。皆所以明筮例。及用九用六之故。学者须于此先知之。</p></li><li><p>易辞本为占辞。故其语在可解不可解之间。惟其在可解不可解之间。故能随所感而曲中肆应不穷。所谓仁者见仁，智者见智也。此易理也。易理与义理不同。例如程传说黄裳元吉。云五尊位。臣居之则羿莽。女居之则女娲武氏。故圣人着为大戒。陈义可谓正大矣。而于易理则大背，以易辞并无着戒之意也。此编只明易理。至其用则任人感触之。</p></li><li><p>卦名皆因卦象而生。卦名不解。因之卦爻辞亦不解。如睽为反目。谓两目不相听。故一目见为此。一目见为彼。三上爻辞是也。此义不知。遂多误解。又如节为符节。合以取信。说文所谓竹约也。乃说者概释为樽节制节。卦义既误。故卦爻辞甘苦之义均不知。六十四卦如此者甚多。兹编所释。先及诸卦得名之义。其名有沿革者。亦并考其异同。如睽归藏作瞿。夬归藏作规等是也。</p></li><li><p>说易之书。莫古于左传国语。其所取象。当然无讹。乃清儒信汉儒。而遗左国。坎变巽。左氏曰。夫从风。以坎为夫也。曰震车也。曰车有震武。以震为车为武也。震变离。曰车说其輹。以震为輹也。尤要者。明夷之谦。即离变艮。左氏曰当鸟。是以艮为鸟也。鸟黔喙也。于是小过飞鸟之象有着。乃后人于此象均不识。依汉儒以震为夫。以干为武。夫易师莫先于左氏。其可信较汉儒为何如。故兹编所取象。除以易证易外。首本之左传国语。以明此最古最确之易象。</p></li><li><p>时训为逸周书之专篇。书云周公所作。其气候皆以卦象为准。故卦气图与时训不能相离。其所准易象。与易经所关最巨。如于屯曰雁北乡。以屯上互艮为雁。于巽曰鸿雁来。亦以巽为鸿雁。而渐之六鸿象得解。以艮为蛤为蜃。艮外坚故与离同象。而易之贝象龟象得解。以兑为斧。以艮为巢为鹰。皆赖以解。易而用覆象半象尤精。如于复曰麋角解。震为鹿。艮为角。角覆在地。故日解。于鼎下曰半夏生。离为夏。巽为艹。初二半离。故曰半夏。而昔儒无知者。(除易林外)兹编所取象。除左国外。多以时训为本。</p></li><li><p>焦氏易林。后儒皆知其言易象。然以象学失传之故。莫有通其义者。如以坤为水。以兑为月。以艮为火。以巽为少妻。以兑为老妇。以正反兑正反震为争讼。(争讼即有言)为说卦所无。而皆为经中所有。说者因误解经。而失其象。故于易林亦不能解。愚求之多年。亦无所入。后读蒙之节云。三夫共妻。莫适为雌。子无名氏。翁不可知。因节中爻震艮。上坎三男俱备。故曰三夫。祇下兑为女象。故曰三夫共妻。震为子。艮为名为翁。上坎为隐伏。故曰无。曰不可知。字字皆从易象生。由此以推。凡林词皆豁然而解。故兹编取象。除左传国语卦气图外。多本易林。</p></li><li><p>易中古文甚多。如场作易。 趑趄作次且。趾作止。佚作失等。不可胜数。先儒除晁说之外。知为古文者甚少。于是竟读易为难易。失为得失。兹编非好异。凡易之古文。必仍其旧例。如需于血。即需于洫是也。</p></li><li><p>古书多音同通用。而易尤甚。如盘。作盘。作盘。作般。邅如。作驙如。甲坼。作甲宅。冶容。作野容。刑剭。作形渥。作刑屋。经纶。作经论。作经伦。羸。作虆。作累。作缧。作累之类。皆音同通借。无是非之可言。而世儒必以习见者为非。罕见者为是。似未观其通。兹编反是。</p></li><li><p>易用覆象。如大过九五之枯杨。用覆巽。丰上六用覆艮。重门击柝。以豫上震为覆艮。荀爽及虞翻皆知之。而不能推行。于是困之有言不信。蒙之再三渎。用覆象者。遂永不得解。岂知左氏明夷之谦曰。于人为言。败言为谗。谦上震。震为言。下艮震覆。故曰败言。言相反故曰谗。易林本之。凡正反震正反兑相背者。不曰争讼。即曰有言。于是困震之有言皆得解。此似我创言之。然仍左氏及易林所已言。我拾其说以证易耳。仍非我说也。</p></li><li><p>卦有卦情。中孚之鹤呜子和。以中爻正反震相对也。故下之震鹤一鸣。三至五即如声而反。故曰子和。(旧解不知子指反震皆自鸣自和)又如兑。朋友讲习。以初至五。正覆兑相对。若对语然。故曰讲习。早商兑。夬四之闻言不信。兑为耳。故曰闻。兑为言。干亦为言。乃兑言向外。与干言相背。故曰不信。此似我创解。然左传归妹之睽。曰西邻责言。不可偿也。归妹兑为西。震为邻。故曰西邻。而震为言。震言外向。与兑言相背。故曰责言。与夬之闻言不信义同也。仍非我说也。</p></li><li><p>同此一爻。而爻辞吉凶不同。如颐六五曰。居贞吉。下又曰不可涉大川。家人九三曰。嗃嗃悔厉吉。下又曰妇子嘻嘻终吝。先儒无详其故者。岂知爻有上下。由此爻上取。而象吉者。下取或凶。下取而象吉者。上取或凶。如渐九三妇孕不育凶。下又曰利御寇是也。易词如此者不可枚举。此三爻特其例耳。治易者如明此例。则事半功倍。</p></li><li><p>易辞与他经不同。他经上下文多相属。易则不然。因易辞皆由象生。观某爻而得甲象。又观某爻而得乙象。故易辞各有所指。上下句义不必相联。如损彖曰利有攸往。指上九也。下又曰曷之用。二簋。可用享。震为簋。坤数二。故曰二簋。则指上下互卦也。又如困贞大人吉。以二五皆阳也。有言不信。以三至上正反兑相背也。旧解无知者。故于上下旬。常强为联属。致杈枒不合。兹编遇此。先指明易辞之说何爻何象。至其意义之不相属者。亦必指明。此自为一义。</p></li><li><p>卦爻辞往往相反。如履彖曰不咥人。爻曰咥人凶。无妄彖曰不利有攸往。爻曰往吉。是也。又大象每相反以见义。如同人曰辨物。无妄曰时育万物。是也。先儒无知其故者。岂知卦有卦义。爻有爻义。象有象义。绝不同也。</p></li><li><p>汉儒以象数解易。与春秋士大夫合。最为正轨。乃郑玄于象之不知者。则用爻辰。取象于星宿。虞翻则用爻变。使变出某卦。以当其象。若此者亦不敢从也。</p></li><li><p>易义有绝不能解者。先儒虽强说之。实皆无当。如同人九四之吉。自象传不能详其故。小畜九二同。易义如此者多有。兹编遇之。必详言其难解之故。偶有揣测。亦不敢自信也。</p></li><li><p>吴挚父先生易说。于大畜云。凡阳之行。遇阴则通。遇阳则阻。故初二皆不进。而三利往。于节云。易以阳在前为塞。阴在前为通。初之不出。以九二在前。二则可出而不出。故有失时之凶。此实全易之精髓。为二千年所未发。愚于易理粗有所入。实以此数语为之阶。故特揭出。以尊师说。</p></li><li><p>眼前事物。皆为易理。俯取即是。例如雄鸡与雄鸡见则死斗。驴马尤甚。若有宿仇者。是何也。阳遇阳也。大畜初九曰。有厉利已。厉危已止也。初有应。但为二三所隔。遇敌故曰有厉。止而不动。则灾免矣。象曰不犯灾。正释厉义也。乃旧解谓厉指四爻。厉若在四。尚何贵此应与乎。不识灾即厉。命二变成坎。以取灾象。岂知大壮初九。壮于趾征凶。夬初九。壮于前趾往不胜。壮伤也。其故皆在阳遇阳。伤之与灾。有何别乎。故夫目前易理。望之似浅。推之实深。昧厥目前。易虽一再言之。总不能知。</p></li></ul>',2)])])}const f=l(s,[["render",t]]);export{d as __pageData,f as default};
